create or replace function private.sync_company_organization_mode_from_locations() returns trigger language plpgsql security definer set search_path to '' as $function$ declare v_company uuid;v_count integer; begin v_company:=coalesce(new.company_id,old.company_id); if v_company is null then return coalesce(new,old); end if; select count(*) into v_count from public.locations where company_id=v_company and status='active'; insert into public.company_settings(company_id,organization_mode) values(v_company,case when v_count>1 then 'multi_site' else 'single_site' end) on conflict(company_id) do update set organization_mode=excluded.organization_mode,updated_at=now(); return coalesce(new,old); end $function$;
drop trigger if exists trg_sync_company_site_mode on public.locations;
create trigger trg_sync_company_site_mode after insert or update of status,company_id or delete on public.locations for each row execute function private.sync_company_organization_mode_from_locations();